#!/usr/bin/env python3
from pathlib import Path

p = Path("android/app/src/main/java/com/streamflixvip/app/ui/player/PlayerScreen.kt")
t = p.read_text()
assert "gestureKind" in t

# rememberCoroutineScope import
if "import androidx.compose.runtime.rememberCoroutineScope" not in t:
    t = t.replace(
        "import androidx.compose.runtime.remember\n",
        "import androidx.compose.runtime.remember\nimport androidx.compose.runtime.rememberCoroutineScope\n",
    )

# gestureScope after playerViewRef
if "gestureScope" not in t:
    t = t.replace(
        "    var playerViewRef by remember { mutableStateOf<PlayerView?>(null) }\n",
        "    var playerViewRef by remember { mutableStateOf<PlayerView?>(null) }\n"
        "    val gestureScope = rememberCoroutineScope()\n",
    )

start = t.find("        // Zonas de gesto:")
end = t.find("        if (errorMessage != null || isRecovering) {")
if start < 0 or end < 0:
    raise SystemExit(f"bounds start={start} end={end}")
new_gestures = "        // Zonas de gesto: 28% esquerda = brilho, 28% direita = volume\n        // Toque = controles; deslize vertical = ajusta (fluido, some sozinho)\n        Box(\n            modifier = Modifier\n                .fillMaxHeight()\n                .fillMaxWidth(0.28f)\n                .align(Alignment.CenterStart)\n                .pointerInput(Unit) {\n                    awaitEachGesture {\n                        val down = awaitFirstDown(requireUnconsumed = false)\n                        var totalY = 0f\n                        var dragging = false\n                        val startLevel = brightnessLevel\n                        drag(down.id) { change ->\n                            totalY += change.positionChange().y\n                            if (!dragging && abs(totalY) > 12f) {\n                                dragging = true\n                                gestureHideJob?.cancel()\n                                gestureKind = \"brightness\"\n                            }\n                            if (dragging) {\n                                change.consume()\n                                val delta = -totalY / size.height.toFloat() * 1.35f\n                                val next = (startLevel + delta).coerceIn(0.01f, 1f)\n                                brightnessLevel = next\n                                gestureValue = next\n                                val act = context as? android.app.Activity\n                                act?.window?.let { w ->\n                                    val lp = w.attributes\n                                    lp.screenBrightness = next\n                                    w.attributes = lp\n                                }\n                            }\n                        }\n                        if (!dragging) {\n                            val pv = playerViewRef\n                            if (pv != null) {\n                                if (pv.isControllerFullyVisible) pv.hideController() else pv.showController()\n                            } else {\n                                controlsVisible = !controlsVisible\n                            }\n                        } else {\n                            gestureHideJob?.cancel()\n                            gestureHideJob = gestureScope.launch {\n                                delay(800)\n                                gestureKind = null\n                            }\n                        }\n                    }\n                },\n        )\n        Box(\n            modifier = Modifier\n                .fillMaxHeight()\n                .fillMaxWidth(0.28f)\n                .align(Alignment.CenterEnd)\n                .pointerInput(Unit) {\n                    awaitEachGesture {\n                        val down = awaitFirstDown(requireUnconsumed = false)\n                        var totalY = 0f\n                        var dragging = false\n                        val startLevel = volumeLevel\n                        drag(down.id) { change ->\n                            totalY += change.positionChange().y\n                            if (!dragging && abs(totalY) > 12f) {\n                                dragging = true\n                                gestureHideJob?.cancel()\n                                gestureKind = \"volume\"\n                            }\n                            if (dragging) {\n                                change.consume()\n                                val delta = -totalY / size.height.toFloat() * 1.35f\n                                val next = (startLevel + delta).coerceIn(0f, 1f)\n                                volumeLevel = next\n                                gestureValue = next\n                                val vol = (next * maxVolume).toInt().coerceIn(0, maxVolume)\n                                audioManager.setStreamVolume(AudioManager.STREAM_MUSIC, vol, 0)\n                            }\n                        }\n                        if (!dragging) {\n                            val pv = playerViewRef\n                            if (pv != null) {\n                                if (pv.isControllerFullyVisible) pv.hideController() else pv.showController()\n                            } else {\n                                controlsVisible = !controlsVisible\n                            }\n                        } else {\n                            gestureHideJob?.cancel()\n                            gestureHideJob = gestureScope.launch {\n                                delay(800)\n                                gestureKind = null\n                            }\n                        }\n                    }\n                },\n        )\n\n        if (gestureKind != null) {\n            Surface(\n                color = Color.Black.copy(alpha = 0.72f),\n                shape = RoundedCornerShape(16.dp),\n                modifier = Modifier.align(Alignment.Center),\n            ) {\n                Column(\n                    modifier = Modifier.padding(horizontal = 22.dp, vertical = 16.dp),\n                    horizontalAlignment = Alignment.CenterHorizontally,\n                ) {\n                    Icon(\n                        imageVector = if (gestureKind == \"brightness\") Icons.Filled.BrightnessHigh else Icons.Filled.VolumeUp,\n                        contentDescription = null,\n                        tint = Color.White,\n                        modifier = Modifier.size(28.dp),\n                    )\n                    Spacer(Modifier.height(8.dp))\n                    Text(\n                        \"${(gestureValue * 100).toInt()}%\",\n                        color = Color.White,\n                        fontSize = 16.sp,\n                    )\n                }\n            }\n        }\n\n"
t = t[:start] + new_gestures + t[end:]
p.write_text(t)
print("patched", len(t))
assert "pointerInput(Unit)" in t
assert "gestureScope.launch" in t
assert "pointerInput(brightnessLevel)" not in t
print("ok")
